class.description:
A [NetwRequest] that is the first argument, before the arguments of [method Netw.action]. Call [method bind] on a node the action spawns, before adding it to the tree. Call [method NetwRequest.deny] to reject the action. The requesting peer undoes its prediction, and its [method NetwActionConfig.revert] handler receives the code and the reason, which is cut to 255 UTF-8 bytes.
[codeblock]
func place_bomb(request: NetwActionRequest, pos: Vector2) -> void:
    var past := Netw.sample(entity, request.view_tick)
    if not past.has_value(&"position"):
        request.deny("no position at that tick")
        return
    var bomb := BOMB.instantiate()
    request.bind(bomb)
    bombs.add_child(bomb)
[/codeblock]
